def _frontier_mix_rank_core(
    frontiers: dict, weights: dict, alpha: float, attribution: bool
) -> str:
    """Shared implementation of :func:`frontier_mix_rank_report` and
    :func:`frontier_rank_attribution`; ``attribution`` selects whether
    each rank entry gains the ``driver`` and ``panels`` keys."""
    case_keys, weight_values, parsed, budgets, panel_keys = (
        _frontier_mix_inputs(frontiers, weights)
    )
    alpha_value = _validate_finite_number(alpha, "alpha")
    if alpha_value <= 0 or alpha_value > 1:
        raise ValueError("alpha must be greater than 0 and at most 1")

    with localcontext() as ctx:
        ctx.prec = _MODEL_PRECISION
        ctx.rounding = ROUND_HALF_EVEN

        total_weight = sum(
            (weight_values[key] for key in case_keys), Decimal(0)
        )

        def _groups(
            index: int, keys: list[str]
        ) -> dict[tuple[str, ...], list]:
            # pick -> [n, weight sum, weighted effect sum]
            groups: dict[tuple[str, ...], list] = {}
            for key in keys:
                point = parsed[key][1][index]
                entry = groups.setdefault(
                    point[3], [0, Decimal(0), Decimal(0)]
                )
                entry[0] += 1
                entry[1] += weight_values[key]
                entry[2] += weight_values[key] * point[0]
            return groups

        def _ranking(
            groups: dict[tuple[str, ...], list], total: Decimal
        ) -> list[tuple[str, ...]]:
            return sorted(
                groups,
                key=lambda pick: (
                    -(groups[pick][1] / total),
                    -(groups[pick][2] / groups[pick][1]),
                    pick,
                ),
            )

        point_strings: list[tuple] = []
        all_tests: list[tuple] = []
        for index, budget in enumerate(budgets):
            groups = _groups(index, case_keys)
            ranking = _ranking(groups, total_weight)

            panel_data: list[tuple] = []
            if attribution:
                # Per (by, key) panel: each pick group's in-group
                # weighted panel effect and the panel rank of the pick.
                members: dict[tuple[str, ...], list[str]] = {}
                for key in case_keys:
                    members.setdefault(
                        parsed[key][1][index][3], []
                    ).append(key)
                for panel in panel_keys:
                    panel_effects: dict[tuple[str, ...], Decimal] = {}
                    for pick, keys in members.items():
                        panel_effects[pick] = sum(
                            (
                                weight_values[key]
                                * parsed[key][1][index][4][panel]
                                for key in keys
                            ),
                            Decimal(0),
                        ) / groups[pick][1]
                    panel_ranking = sorted(
                        panel_effects,
                        key=lambda pick: (
                            -(groups[pick][1] / total_weight),
                            -panel_effects[pick],
                            pick,
                        ),
                    )
                    panel_data.append(
                        (
                            panel,
                            panel_effects,
                            {
                                pick: position
                                for position, pick in
                                enumerate(panel_ranking, start=1)
                            },
                        )
                    )

            rank_strings: list[str] = []
            for rank, pick in enumerate(ranking, start=1):
                n, weight_sum, effect_sum = groups[pick]
                stable = True
                for dropped in case_keys:
                    remaining = [k for k in case_keys if k != dropped]
                    sub_groups = _groups(index, remaining)
                    if pick not in sub_groups:
                        stable = False
                        break
                    sub_total = total_weight - weight_values[dropped]
                    sub_ranking = _ranking(sub_groups, sub_total)
                    if sub_ranking.index(pick) + 1 != rank:
                        stable = False
                        break
                rank_string = (
                    '{"pick":'
                    + json.dumps(
                        list(pick), ensure_ascii=False,
                        separators=(",", ":"),
                    )
                    + ',"n":' + str(n)
                    + ',"support":' + _format6(weight_sum / total_weight)
                    + ',"effect":' + _format6(effect_sum / weight_sum)
                    + ',"rank":' + str(rank)
                    + ',"stable":' + ("true" if stable else "false")
                )
                if attribution:
